"""Brute-force solvers for Independent Set and Clique, from the definitions."""

from __future__ import annotations

from itertools import combinations


def _edge_set(instance):
    return {frozenset((u, v)) for u, v in instance["edges"]}


def has_independent_set(instance):
    n = instance["n"]
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    edges = _edge_set(instance)
    for subset in combinations(range(n), k):
        if all(frozenset((u, v)) not in edges for u, v in combinations(subset, 2)):
            return True
    return False


def has_clique(instance):
    n = instance["n"]
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    edges = _edge_set(instance)
    for subset in combinations(range(n), k):
        if all(frozenset((u, v)) in edges for u, v in combinations(subset, 2)):
            return True
    return False


def solve_independent_set(instance):
    return has_independent_set(instance)


def solve_clique(instance):
    return has_clique(instance)
